//"use strict"; // different chrome versions treat it differently

var FU = FU || {};

FU.dictionaryCurrentWidth = 12; // having precalculated value speed up start by 150ms

FU.dictionaryWidth = function (aDictionary, aShowLongest) {
    // find max key length in dictionary (it's slow, so don't call it often and cache it until you add longer word)
    //"use strict";
    var key, len, w = 0;
    for (key in aDictionary) {
        if (aDictionary.hasOwnProperty(key)) {
            len = key.length;
            if (len > w) {
                w = len;
            }
        }
    }
    if (aShowLongest) {
        for (key in aDictionary) {
            if (aDictionary.hasOwnProperty(key)) {
                if ((key.length > w) || (key.length > FU.dictionaryCurrentWidth)) {
                    console.log(key.length, key);
                }
            }
        }
    }
    return w;
};

FU.searchRoumaji = function (aText) {
    // search by roumaji match (e.g. atarashii --> atarashii, maatarashi)
    //"use strict";
    var k, r = [], s = aText.trim().toLowerCase();
    for (k in FU.dictionary) {
        if (FU.dictionary.hasOwnProperty(k)) {
            if (FU.dictionary[k][0].match(s)) {
                r.push({jp: k, roumaji: FU.dictionary[k][0], en: FU.dictionary[k][1] });
            }
        }
    }
    return r;
};

